using System.Text;
using FinanceTracker.Generated.Shared;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace FinanceTracker.Generated.Attributes;

/// <summary>
/// Adds the <c>InjectionCategory</c> attribute, which says which registration method and projects register a class.
/// </summary>
[Generator]
public class InjectionCategoryAttributeGenerator : IIncrementalGenerator
{
    /// <summary>
    /// The attribute's source.
    /// </summary>
    private const string AttributeSourceCode = $$"""
                                                 // <auto-generated/>
                                                 using FinanceTracker.Generated.Enums;
                                                 namespace {{SourceGeneratorConstants.GeneratedNamespace}}.Attributes
                                                 {
                                                     /// <summary>
                                                     /// Which registration method and projects register the class.
                                                     /// </summary>
                                                     /// <param name="Category">Which registration method.</param>
                                                     /// <param name="Destination">Which projects.</param>
                                                     [System.AttributeUsage(System.AttributeTargets.Class)]
                                                     internal class {{SourceGeneratorConstants.InjectionCategoryAttributeName}}({{SourceGeneratorConstants.InjectionCategoryEnumName}} Category, {{SourceGeneratorConstants.ServiceDestinationEnumName}} Destination) : System.Attribute
                                                     {
                                                         /// <summary>
                                                         /// Which registration method.
                                                         /// </summary>
                                                         public {{SourceGeneratorConstants.InjectionCategoryEnumName}} Category { get; } = Category;
                                                         /// <summary>
                                                         /// Which projects.
                                                         /// </summary>
                                                         public {{SourceGeneratorConstants.ServiceDestinationEnumName}} Destination { get; } = Destination;
                                                     }
                                                 }
                                                 """;

    /// <inheritdoc/>
    public void Initialize(IncrementalGeneratorInitializationContext context) =>
        context.RegisterPostInitializationOutput(ctx => ctx.AddSource(
            $"{SourceGeneratorConstants.InjectionCategoryAttributeName}.g.cs",
            SourceText.From(AttributeSourceCode, Encoding.UTF8)));
}
